import { expect, test, uniqueName } from "../../fixtures";

test.describe("VEN-04: manage vendors", () => {
  test(
    "the same vendor name is allowed in a different tenant",
    { tag: "@VEN-04" },
    async ({ apiAs }) => {
      // Arrange: a vendor with the same name already exists in another tenant.
      // The name is made unique so repeated or parallel runs do not collide.
      const name = uniqueName("Acme Freight");
      const otherTenant = await apiAs("otherTenant");
      const existing = await otherTenant.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: "ops@globex-freight.example",
        },
      });
      expect(existing.status(), "seed vendor in Globex Procurement").toBe(201);

      // Act: the member from Northwind creates a vendor with that same name.
      const member = await apiAs("member");
      const response = await member.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      expect(response.status()).toBe(201);
      const created = await response.json();
      expect(created.name).toBe(name);
      expect(created.id).toBeTruthy();
    },
  );
});
